mapper.select:
select distinct aa.* from( SELECT I.OURTRADERNAME ourTradeName, decode(I.BUSINESSTYPE,'BOND', (select TRADE_MARKET from fin_product where FINPROD_market_ID = ts.SECID), 'REPO',decode(tr.market, 'IB', '01', 'SH', '03', 'SZ', '04')) market, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed, I.ourdepositaccountname, I.EXECID execid ,I.BUSINESSTYPE businesstype ,decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO','') securityid ,decode(I.BUSINESSTYPE, 'BOND', I.SYMBOL, 'REPO', '') symbol ,nvl(ts.ps,tr.ps) side ,ts.Prinamt prinamt ,tr.Repoamt repoamt ,I.LASTQTY lastqty ,tmi.SUMMATCHNUM lastqtyready
,decode(I.BUSINESSTYPE,'BOND',I.PRICE,'REPO',I.PRICE*100) price ,decode(I.BUSINESSTYPE, 'BOND', I.DIRTYPRICE, 'REPO', '') dirtyprice ,decode(I.BUSINESSTYPE, 'BOND', I.UNDERLYINGYIELD2*100, 'REPO', '') underlyingyield2 ,I.TRADEDATE tradedate ,decode(I.BUSINESSTYPE, 'BOND', I.ACCRUEDINTERESTAMT, 'REPO', '') accruedinterestamt ,I.ACCRUEDINTERESTTOTALAMT accruedinteresttotalamt ,I.TRADECASHAMT tradecashamt ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.SETTLCURRAMT2) settlcurramt2 ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.TRADELIMITDAYS) tradelimitdays ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.CASHHOLDINGDAYS) cashholdingdays ,ROUND(NVL(decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)), 0)/ NVL(I.LASTQTY, 1) , 4) percent, decode(I.BUSINESSTYPE, 'BOND', I.STRIKEYIELD*100, 'REPO', '') strikeyield, CASE WHEN tmi.SUMMATCHNUM IS NULL or tmi.SUMMATCHNUM=0 THEN '02' WHEN decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)) =I.LASTQTY then '01' ELSE '03' END matchStatus, QUOTE.QUOTEID reference, QUOTE.ENTRUST_ID entrustId, I.CB_FPRICE_AMT, I.SC_FPRICE_AMT, case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else COUNTERDEPOSITACCOUNTNUMBER end as OURDEPOSITACCOUNTNUMBER, su.USER_NAME userName FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID
LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID LEFT JOIN ( SELECT SUM(MATCH_NUM) SUMMATCHNUM,CSTP_TRADE_ID FROM trd_match_info group by CSTP_TRADE_ID ) tmi on tmi.CSTP_TRADE_ID = I.EXECID LEFT JOIN ( SELECT i.EXECID ,listagg(nvl(iqb.ENTRUST_ID , nvl(iqc.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID,iqerr.ENTRUST_ID) )), ',') WITHIN GROUP ( ORDER BY i.UPDATETIME DESC) AS ENTRUST_ID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID) QUOTEID FROM INTERF_CSTP_TRADE i LEFT JOIN IBU_QUOTE_BOND_DET iqbd ON i.EXECID = iqbd.EXECID LEFT JOIN IBU_QUOTE_BOND iqb ON iqbd.QUOTE_ID = iqb.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE iqerb ON iqb.QUOTE_ID = iqerb.QUOTE_ID LEFT JOIN IBU_QUOTE_CREP iqc ON i.EXECID = iqc.EXECID LEFT JOIN IBU_QUOTE_ETR_RE iqerr ON iqc.QUOTE_ID = iqerr.QUOTE_ID GROUP BY i.EXECID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID) ) QUOTE ON QUOTE.EXECID=I.EXECID
AND I.BUSINESSTYPE in ('BOND','REPO')
AND I.BUSINESSTYPE = #{finprodType}
AND nvl(ts.ps,tr.ps) = #{ps}
AND (ts.SECID = #{finprodId} or ts.SECID = CONCAT(#{finprodId},'.IB'))
AND I.EXECID IN
#{item}
AND (TRADEDATE BETWEEN #{tradeDateBegin} AND #{tradeDateEnd})
AND to_date(TRADEDATE,'yyyy-mm-dd') >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND to_date(TRADEDATE,'yyyy-mm-dd') <= to_date(#{entrustEndDate},'yyyy-mm-dd')
and I.OURDEPOSITACCOUNTNUMBER = #{secAcctId}
and I.OURTRADERNAME LIKE CONCAT('%',CONCAT(#{ourTradeName},'%'))
and I.TRADELIMITDAYS >=${repoTerm}
and I.TRADELIMITDAYS <= ${repoTerm2}
and I.TRADECASHAMT >=${priceAmt}
and I.TRADECASHAMT <= ${priceAmt2}
and (nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) = #{entrustBusiCode} or nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) is null )
and QUOTE.quoteId = #{quoteId}
and ts.SECID = #{entrustFinprodId}
and decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED) = #{entrustSettleSpeed}
and nvl(ts.ps,tr.ps) = #{entrustPs}
and I.TRADELIMITDAYS = #{entrustTradelimitdays}
) aa
AND aa.matchStatus IN
#{item}
and aa.market = #{tradeMarket}
and aa.settleSpeed = #{settleSpeed}
and aa.tradelimitdays = #{tradelimitdays}

select lastqty from INTERF_CSTP_TRADE

	updatetime = (select max(t.updatetime)
	from interf_cstp_trade t


			t.execid = #{fTradeId,jdbcType=VARCHAR}


	)

		and execid = #{fTradeId}
